import{Module}from'../../core/index.js';import{THREE,materials,box,solid,crossProfile,roundedRect,filmProfile,ring}from'./geometry.js';import{spec}from'./dimensions.js';import{addPolarity}from'./stickers.js';
/** Exact own U013 orange accessory;all unmeasured installation details inferred. */
export class TerminalPlug extends Module{static meta={id:'m5stack.unit.adc.terminal-plug',name:'ADC U013 own removable orange2P plug',sku:'U013 accessory',connector:spec.terminal.connector};build(){const frame=new THREE.Group();frame.name='ADC U013 own orange removable plug';this.body.add(frame);const orange=materials.plastic(0xf28a36,{roughness:.64}),tin=materials.metal(0xb6bbad,{roughness:.42}),parts=[],b=(s,p,n,m=orange)=>{const o=box(frame,s,p,m,'ADC U013 plug '+n);parts.push(o);return o;};
 const t=roundedRect(6.8,2.5,.12);for(const x of spec.terminal.pinX)t.holes.push(roundedRect(1.1,1.1,.08,{cx:x,cy:-.35,path:new THREE.Path()}));const tongue=crossProfile(frame,t,3.7,[0,0,0],orange,'ADC U013 actual mating tongue with two true pin bores');parts.push(tongue);
 const floor=b([8,9.6,.5],[0,4.8,-.55],'channel floor'),deck=b([8,9.6,.61],[0,4.8,4.755],'actual front orange deck below physical polarity film'),walls=[];for(const x of[-3.75,0,3.75])walls.push(b([x===0?.4:.5,9.6,4.75],[x,4.8,2.075],'actual separating channel wall'));
 const entryProfile=roundedRect(8,5.8,.15,{cy:2.2});for(const x of spec.terminal.pinX){const h=new THREE.Path();h.absarc(x,1,1.25,0,Math.PI*2,false);entryProfile.holes.push(h);}const entry=crossProfile(frame,entryProfile,.65,[0,9.6,0],orange,'ADC U013 two real round wire-entry bores');parts.push(entry);
 const springs=[],cages=[],backs=[];for(const x of spec.terminal.pinX){for(const sx of[-1,1])springs.push(b([.12,5.5,.65],[x+sx*.335,-1.05,-.35],'actual female mating spring',tin));backs.push(b([2.65,.2,3.9],[x,1.05,1.45],'actual deep conductor stop',tin));cages.push(b([2.65,7.5,.18],[x,4.9,-.18],'actual lower conducting cage',tin));for(const sx of[-1,1])cages.push(b([.14,7.5,3.9],[x+sx*1.255,4.9,1.45],'actual side conducting cage',tin));cages.push(b([2.55,7.5,.18],[x,4.9,3.35],'fixed upper pressure plate;no guessed screw travel',tin));}
 const film=solid(frame,filmProfile(),.04,[0,2.1,5.06],materials.plastic(0xd9d1ba,{roughness:.86}),'ADC U013 actual plug polarity adhesive film');film.userData={role:'physical-label-substrate',appearanceThicknessInferred:true};this.adcPlugAssembly={frame,parts,tongue,floor,deck,walls,entry,springs,cages,backs,film};this.unitStickers=addPolarity(this,film);}}
